 var ranges;
 let seed = Math.random() * 1241;
 var mySize;
let str_wei = 0;
let x_space;

 // colors
 let colors0 = "281914-1a1a1a-202020-242e30".split("-").map((a) => "#" + a);
 let colors1 = "fef9fb-fafdff-ffffff-fcfbf4-f9f8f6".split("-").map((a) => "#" + a);
 let colors2 = "8c75ff-c553d2-2dfd60-2788f5-23054f-f21252-8834f1-c4dd92-184fd3-f9fee2-2E294E-541388-F1E9DA-FFD400-D90368-e9baaa-ffa07a-164555-ffe1d0-acd9e7-4596c7-6d8370-e45240-21d3a4-3303f9-cd2220-173df6-244ca8-a00360-b31016".split("-").map((a) => "#" + a);
 let color1, color2;
 let colorselet = [];
 let plus, margin;
 let tile_count = 10;
 let h_size;

 function setup() {
 	// pixelDensity(5);
 	randomSeed(seed);
 	mySize = max(windowWidth, windowHeight);
 	createCanvas(1112, 834);
 	background("#202020");
 	margin = mySize / 50;
 	ranges = random([100,150,200,250]);
 	color1 = random(colors1);
 	color2 = random(colors2);
 	plus = 0;
 	colorselet[0] = random(colors2);
 	colorselet[1] = random(colors2);
 	colorselet[2] = random(colors2);
 	//colorselet[3] = random(colors2);
 	h_size = int(random(200, 100));
	 x_space = int(random(20,50));
 }

 function draw() {
 	// background("#202020");
 	randomSeed(seed);
 	noiseSeed(seed);

 	noFill();
 	let H = random(1.25, 0.75) / 5;
 	let aa = random(1, 0.8) * 1.25;
 	let res = random(0.005, 0.001);
 	for (let i = 0; i < ranges; i++) {
 		strokeWeight(str_wei);
 		stroke(random(colorselet));
 		if (ranges % 3 == 0) {
 			drawingContext.shadowColor = random(colors0);
 			drawingContext.shadowOffsetX = str_wei;
 			drawingContext.shadowOffsetY = str_wei;
 			drawingContext.shadowBlur = 0;
 		} else {
 			drawingContext.shadowColor = random(colors1);
 			drawingContext.shadowOffsetX = str_wei;
 			drawingContext.shadowOffsetY = str_wei;
 			drawingContext.shadowBlur = 0;
 		}

 		for (let x = -width * 3; x < width * 3; x += x_space) {
 			let n = noise(x * 0.01, i * 0.01, frameCount * res);
 			let y = map(n, -0.25, 1, height * aa, height * H);
 			point(x + 10 * (plus - 5), y - plus);
 		}
 	}
  if(str_wei <4){
		str_wei += 0.01;
	}

 	if (plus < 2 * height / h_size) {
 		plus += random(0.1, 0.05);

 	} else {
 		drawingContext.shadowColor = random(colors1);
 		drawingContext.shadowOffsetX = 0;
 		drawingContext.shadowOffsetY = 0;
 		drawingContext.shadowBlur = 0;

 		//frame

 		noFill();
 		stroke("#202020");
 		strokeWeight(margin);
 		//rect(0, 0, width, height);
 		noLoop();
 	}
 }

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

